static int test_ldexpl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(ldexpl_vec)/sizeof(ldexpl_vec[0]); i++) {
        long double y = ldexpl(ldexpl_vec[i].x0, ldexpl_vec[i].x1);
        result += check_long_double("ldexpl", ldexpl_vec[i].line, LDEXPL_PREC, ldexpl_vec[i].y, y);
    }
    return result;
}

