static int test_scalbnl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(scalbnl_vec)/sizeof(scalbnl_vec[0]); i++) {
        long double y = scalbnl(scalbnl_vec[i].x0, scalbnl_vec[i].x1);
        result += check_long_double("scalbnl", scalbnl_vec[i].line, SCALBNL_PREC, scalbnl_vec[i].y, y);
    }
    return result;
}

