static int test_powl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(powl_vec)/sizeof(powl_vec[0]); i++) {
        long double y = powl(powl_vec[i].x0, powl_vec[i].x1);
        result += check_long_double("powl", powl_vec[i].line, POWL_PREC, powl_vec[i].y, y);
    }
    return result;
}
