static int test_fdiml(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(fdiml_vec)/sizeof(fdiml_vec[0]); i++) {
        long double y = fdiml(fdiml_vec[i].x0, fdiml_vec[i].x1);
        result += check_long_double("fdiml", fdiml_vec[i].line, FDIML_PREC, fdiml_vec[i].y, y);
    }
    return result;
}
