static int test_remainderl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(remainderl_vec)/sizeof(remainderl_vec[0]); i++) {
        long double y = remainderl(remainderl_vec[i].x0, remainderl_vec[i].x1);
        result += check_long_double("remainderl", remainderl_vec[i].line, REMAINDERL_PREC, remainderl_vec[i].y, y);
    }
    return result;
}
