static int test_dreml(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(dreml_vec)/sizeof(dreml_vec[0]); i++) {
        long double y = dreml(dreml_vec[i].x0, dreml_vec[i].x1);
        result += check_long_double("dreml", dreml_vec[i].line, DREML_PREC, dreml_vec[i].y, y);
    }
    return result;
}
