static int test_atanhl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(atanhl_vec)/sizeof(atanhl_vec[0]); i++) {
        long double y = atanhl(atanhl_vec[i].x);
        result += check_long_double("atanhl", atanhl_vec[i].line, ATANHL_PREC, atanhl_vec[i].y, y);
    }
    return result;
}
