static int test_atanl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(atanl_vec)/sizeof(atanl_vec[0]); i++) {
        long double y = atanl(atanl_vec[i].x);
        result += check_long_double("atanl", atanl_vec[i].line, ATANL_PREC, atanl_vec[i].y, y);
    }
    return result;
}
