static int test_coshl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(coshl_vec)/sizeof(coshl_vec[0]); i++) {
        long double y = coshl(coshl_vec[i].x);
        result += check_long_double("coshl", coshl_vec[i].line, COSHL_PREC, coshl_vec[i].y, y);
    }
    return result;
}
