static int test_erfcl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(erfcl_vec)/sizeof(erfcl_vec[0]); i++) {
        long double y = erfcl(erfcl_vec[i].x);
        result += check_long_double("erfcl", erfcl_vec[i].line, ERFCL_PREC, erfcl_vec[i].y, y);
    }
    return result;
}
