static int test_exp10l(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(exp10l_vec)/sizeof(exp10l_vec[0]); i++) {
        long double y = exp10l(exp10l_vec[i].x);
        result += check_long_double("exp10l", exp10l_vec[i].line, EXP10L_PREC, exp10l_vec[i].y, y);
    }
    return result;
}
