static int test_exp2l(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(exp2l_vec)/sizeof(exp2l_vec[0]); i++) {
        long double y = exp2l(exp2l_vec[i].x);
        result += check_long_double("exp2l", exp2l_vec[i].line, EXP2L_PREC, exp2l_vec[i].y, y);
    }
    return result;
}
