static int test_expl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(expl_vec)/sizeof(expl_vec[0]); i++) {
        long double y = expl(expl_vec[i].x);
        result += check_long_double("expl", expl_vec[i].line, EXPL_PREC, expl_vec[i].y, y);
    }
    return result;
}
