static int test_logp1l(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(logp1l_vec)/sizeof(logp1l_vec[0]); i++) {
        long double y = logp1l(logp1l_vec[i].x);
        result += check_long_double("logp1l", logp1l_vec[i].line, LOGP1L_PREC, logp1l_vec[i].y, y);
    }
    return result;
}
