static int test_logl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(logl_vec)/sizeof(logl_vec[0]); i++) {
        long double y = logl(logl_vec[i].x);
        result += check_long_double("logl", logl_vec[i].line, LOGL_PREC, logl_vec[i].y, y);
    }
    return result;
}
