static int test_roundl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(roundl_vec)/sizeof(roundl_vec[0]); i++) {
        long double y = roundl(roundl_vec[i].x);
        result += check_long_double("roundl", roundl_vec[i].line, ROUNDL_PREC, roundl_vec[i].y, y);
    }
    return result;
}

