static int test_sinhl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(sinhl_vec)/sizeof(sinhl_vec[0]); i++) {
        long double y = sinhl(sinhl_vec[i].x);
        result += check_long_double("sinhl", sinhl_vec[i].line, SINHL_PREC, sinhl_vec[i].y, y);
    }
    return result;
}
