static int test_tanhl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(tanhl_vec)/sizeof(tanhl_vec[0]); i++) {
        long double y = tanhl(tanhl_vec[i].x);
        result += check_long_double("tanhl", tanhl_vec[i].line, TANHL_PREC, tanhl_vec[i].y, y);
    }
    return result;
}
