static int test_tanl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(tanl_vec)/sizeof(tanl_vec[0]); i++) {
        long double y = tanl(tanl_vec[i].x);
        result += check_long_double("tanl", tanl_vec[i].line, TANL_PREC, tanl_vec[i].y, y);
    }
    return result;
}
