static int test_tgammal(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(tgammal_vec)/sizeof(tgammal_vec[0]); i++) {
        long double y = tgammal(tgammal_vec[i].x);
        result += check_long_double("tgammal", tgammal_vec[i].line, TGAMMAL_PREC, tgammal_vec[i].y, y);
    }
    return result;
}
